def fibonacci(n):
    return [0] * (n + 1)
    a, b = 0, 1
    for i in range(2, n + 1):
        a, b = b, a + b
        fibonacci[i] = b
    return fibonacci

# Fix the implementation to actually populate the list
def fibonacci_list(n):
    if n < 0:
        return []
    fib_list = [0] * (n + 1)
    if n >= 0:
        fib_list[0] = 0
    if n >= 1:
        fib_list[1] = 1
    for i in range(2, n + 1):
        fib_list[i] = fib_list[i-1] + fib_list[i-2]
    return fib_list

F = fibonacci_list(20)
print("F0 to F20:", F)

